const previo = $('When Executed by Another Workflow').first().json;
const m = previo.mensaje.toLowerCase();

let categoria = '', encontrado = false;

const proyectos = /levstamp|aptis|british council|tu home office|home office|afiliados amazon|amazon afiliados|wedding planner|nuptial|\bboda\b|\bnovios\b|\bjarvis\b/;
if (proyectos.test(m)) { categoria = 'proyecto'; encontrado = true; }

if (!encontrado && /dia libre|de descanso|poco puedo|nada que hacer|sin disponibilidad/.test(m)) {
  categoria = 'estado_dia'; encontrado = true;
}
if (!encontrado && /\b(ya lo he hecho|ya lo hice|terminado|listo,? ya esta|hecho ya)\b/.test(m)) {
  categoria = 'completado'; encontrado = true;
}
if (!encontrado && /\b(novia|novio|esposa|esposo|pareja|mi hijo|mi hija|mi familia|vivo en|trabajo en|estudio en)\b/.test(m)) {
  categoria = 'personal'; encontrado = true;
}

return [{ json: { usuario_id: previo.usuario_id, mensaje: previo.mensaje, categoria, contenido: previo.mensaje, guardar: true, encontrado_por_palabra_clave: encontrado } }];

