const previo = $('Detectar por palabra clave').first().json;
const raw = $json.text ?? $json.response ?? $json.output ?? '';
const match = String(raw).match(/\{[\s\S]*\}/);

// Si Llama no devuelve JSON (se pone a conversar, etc.), no se pierde el mensaje:
// se guarda tal cual en 'general' en vez de descartarlo en silencio.
if (!match) {
  return [{ json: { usuario_id: previo.usuario_id, guardar: true, categoria: 'general', contenido: previo.mensaje } }];
}

try {
  const parsed = JSON.parse(match[0]);
  const categoriaOriginal = String(parsed.categoria ?? '').toLowerCase();
  let categoria = 'general';
  if (categoriaOriginal.includes('preferencia')) categoria = 'preferencia';
  else if (categoriaOriginal.includes('objetivo')) categoria = 'objetivo';
  else if (categoriaOriginal.includes('tarea')) categoria = 'tarea';
  else if (categoriaOriginal.includes('decision') || categoriaOriginal.includes('decisión')) categoria = 'decision';

  const guardar = parsed.guardar === true || String(parsed.guardar).toLowerCase() === 'true';
  return [{ json: { usuario_id: previo.usuario_id, guardar, categoria, contenido: guardar ? String(parsed.contenido ?? previo.mensaje).trim() : '' } }];
} catch (error) {
  return [{ json: { usuario_id: previo.usuario_id, guardar: true, categoria: 'general', contenido: previo.mensaje } }];
}
